// 2. Grab elements from the HTML
const blogContainer = document.getElementById('blogContainer');
const searchInput = document.getElementById('searchInput');
const categoryFilter = document.getElementById('categoryFilter');
const header = document.querySelector('header'); 
const fullPostView = document.getElementById('fullPostView');
const fullPostContent = document.getElementById('fullPostContent');
const postHeaderImage = document.querySelector('.post-header-image');
const backBtn = document.getElementById('backBtn');

// 3. Render Grid Function
function renderBlogs(blogsToDisplay) {
    blogContainer.innerHTML = '';
    
    if (blogsToDisplay.length === 0) {
        blogContainer.innerHTML = '<p class="no-results">No articles found matching your criteria.</p>';
        return;
    }

    blogsToDisplay.forEach(blog => {
        const card = document.createElement('div');
        card.className = 'blog-card';
        
        // NEW: Upgraded card structure for better hover effects
        card.innerHTML = `
            <div class="img-wrapper">
                <img src="${blog.image}" alt="${blog.title}" class="blog-img">
            </div>
            <div class="blog-content">
                <span class="blog-category">${blog.category}</span>
                <h2 class="blog-title">${blog.title}</h2>
                <p class="blog-excerpt">${blog.excerpt}</p>
                <div class="read-more">Read Article <span>→</span></div>
            </div>
        `;
        
        card.addEventListener('click', () => openFullPost(blog.id));
        blogContainer.appendChild(card);
    });
}

// 4. Function to open the full post
function openFullPost(id) {
    const blog = blogData.find(b => b.id === id);
    
    // Hide grid and header
    blogContainer.classList.add('hidden');
    header.classList.add('hidden');
    
    // Show full post view
    fullPostView.classList.remove('hidden');
    
    // Set header image as a big hero banner
    postHeaderImage.innerHTML = `<img src="${blog.image}" class="post-header-img-full" alt="${blog.title}">`;
    
    // Inject content
    fullPostContent.innerHTML = `
        <span class="blog-category">${blog.category}</span>
        <h1>${blog.title}</h1>
        <div class="full-post-body">${blog.content}</div>
    `;
    
    window.scrollTo(0, 0);
}

// 5. Function to go back to the grid
backBtn.addEventListener('click', () => {
    fullPostView.classList.add('hidden');
    blogContainer.classList.remove('hidden');
    header.classList.remove('hidden');
    window.scrollTo(0, 0);
});

// 6. Search and Filter Logic
function filterBlogs() {
    const searchTerm = searchInput.value.toLowerCase();
    const selectedCategory = categoryFilter.value;

    const filtered = blogData.filter(blog => {
        const matchesSearch = blog.title.toLowerCase().includes(searchTerm) || 
                              blog.excerpt.toLowerCase().includes(searchTerm);
        const matchesCategory = selectedCategory === 'all' || blog.category === selectedCategory;
        return matchesSearch && matchesCategory;
    });
    renderBlogs(filtered);
}

searchInput.addEventListener('input', filterBlogs);
categoryFilter.addEventListener('change', filterBlogs);

// 7. Initial load
renderBlogs(blogData);
